/// <summary>ä¾å­˜ãƒ‘ãƒƒã‚±ãƒ¼ã‚¸ã‚’ä½¿ã‚ãšã«æ¤œè¨¼é …ç›®ã‚’å®Ÿè¡Œã™ã‚‹ãƒ†ã‚¹ãƒˆé›†ã§ã™ã€‚</summary>
sealed class TestSuite
{
    private readonly List<(string Name, Action Test)> tests = [];
    /// <summary>åå‰ä»˜ãã®æ¤œè¨¼å‡¦ç†ã‚’ãƒ†ã‚¹ãƒˆé›†ã¸è¿½åŠ ã—ã¾ã™ã€‚</summary>
    /// <param name="name">çµæœè¡¨ç¤ºã«ä½¿ã†æ¤œè¨¼åã§ã™ã€‚</param>
    /// <param name="test">å®Ÿè¡Œã™ã‚‹æ¤œè¨¼å‡¦ç†ã§ã™ã€‚</param>
    public void Add(string name, Action test) => tests.Add((name, test));
    /// <summary>ç™»éŒ²ã—ãŸæ¤œè¨¼ã‚’é †ã«å®Ÿè¡Œã—ã€ä»¶æ•°ãƒ»ãƒ­ã‚°ãƒ»çµ‚äº†ã‚³ãƒ¼ãƒ‰ã‚’åŒã˜åˆ†é¡çµæœã‹ã‚‰ç”Ÿæˆã—ã¾ã™ã€‚</summary>
    /// <returns>å…¨ä»¶æˆåŠŸã¯0ã€å¤±æ•—ã‚ã‚Šã¯1ã€å¤±æ•—ãªã—ã§æœªæ¤œè¨¼ã‚ã‚Šã¯2ã®çµæœã§ã™ã€‚</returns>
    public TestSuiteResult Run(TextWriter? output = null, TextWriter? error = null)
    {
        output ??= Console.Out;
        error ??= Console.Error;
        var passed = 0;
        var skipped = 0;
        var failed = 0;
        foreach (var (name, test) in tests)
        {
            try { test(); passed++; output.WriteLine($"æˆåŠŸ: {name}"); }
            catch (TestSkippedException exception)
            {
                skipped++;
                output.WriteLine($"æœªæ¤œè¨¼: {name}: {exception.Message}");
            }
            catch (DiagnosticTestFailure exception) { failed++; error.WriteLine($"å¤±æ•—: {name}: {exception.Message}"); }
            catch (Exception exception) { failed++; error.WriteLine($"å¤±æ•—: {name}: {exception.Message}"); }
        }
        var exitCode = failed > 0 ? 1 : skipped > 0 ? 2 : 0;
        var result = new TestSuiteResult(passed, skipped, failed, tests.Count, exitCode);
        output.WriteLine($"çµæœ: {result.Passed}æˆåŠŸ, {result.Skipped}æœªæ¤œè¨¼, {result.Failed}å¤±æ•— / {result.Total}é …ç›®");
        return result;
    }
}

/// <summary>ãƒ†ã‚¹ãƒˆé›†ã®è¡¨ç¤ºä»¶æ•°ã¨ãƒ—ãƒ­ã‚»ã‚¹çµ‚äº†ã‚³ãƒ¼ãƒ‰ã«ä½¿ã†å…±é€šã®æœ€çµ‚é›†è¨ˆã§ã™ã€‚</summary>
/// <param name="Passed">æ­£å¸¸ã«å®Œäº†ã—ãŸæ¤œè¨¼æ•°ã§ã™ã€‚</param>
/// <param name="Skipped">ç’°å¢ƒåˆ¶ç´„ãªã©ã§æœªæ¤œè¨¼ã¨ãªã£ãŸæ¤œè¨¼æ•°ã§ã™ã€‚</param>
