sealed class TestSkippedException(string message) : Exception(message);

/// <summary>ãƒ†ã‚¹ãƒˆç”¨ã®æœ€å°é™ã®æ¡ä»¶ç¢ºèªã¨ä¾‹å¤–ç¢ºèªã‚’æä¾›ã—ã¾ã™ã€‚</summary>
static class Assert
{
    /// <summary>ç’°å¢ƒåˆ¶ç´„ã«ã‚ˆã‚Šå®Ÿæ–½ã§ããªã„æ¤œè¨¼ã‚’æˆåŠŸä»¶æ•°ã‹ã‚‰åˆ†ã‘ã¾ã™ã€‚</summary>
    /// <param name="reason">æ¤œè¨¼ã§ããªã‹ã£ãŸç†ç”±ã§ã™ã€‚</param>
    public static void Skip(string reason) => throw new TestSkippedException(reason);
    /// <summary>æ¡ä»¶ãŒçœŸã§ã‚ã‚‹ã“ã¨ã‚’ç¢ºèªã—ã¾ã™ã€‚</summary>
    public static void True(bool condition, string message = "æ¡ä»¶ãŒçœŸã§ã¯ã‚ã‚Šã¾ã›ã‚“ã€‚") { if (!condition) throw new Exception(message); }
    /// <summary>æ¡ä»¶ãŒå½ã§ã‚ã‚‹ã“ã¨ã‚’ç¢ºèªã—ã¾ã™ã€‚</summary>
    public static void False(bool condition, string message = "æ¡ä»¶ãŒå½ã§ã¯ã‚ã‚Šã¾ã›ã‚“ã€‚") => True(!condition, message);
    /// <summary>æœŸå¾…å€¤ã¨å®Ÿéš›ã®å€¤ãŒç­‰ã—ã„ã“ã¨ã‚’ç¢ºèªã—ã¾ã™ã€‚</summary>
    public static void Equal<T>(T expected, T actual, string? message = null)
    {
        if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception(message ?? $"æœŸå¾…å€¤: {expected} / å®Ÿéš›: {actual}");
    }
